def illegal_kickoff_position(context: RuleContext, robot: dict[str, Any], game: Any) -> CheckResult:
    field = context.field
    if field is None:
        return CheckResult.fail()
    half_length = field.length / 2
    y_limit = field.width / 2 + ILLEGAL_POSITION_FIELD_Y_MARGIN
    position = vec3(robot.get("position"))
    x, y, _ = position
    if abs(x) > half_length + POSITION_TOLERANCE or abs(y) > y_limit:
        return CheckResult.pass_(
            reason="illegalPosition",
            evidence=illegal_position_evidence(
                "field_boundary",
                "Robot position is outside the field boundary tolerance.",
                position,
                [
                    {"name": "absX", "value": abs(x), "unit": "m", "threshold": half_length + POSITION_TOLERANCE, "operator": "<="},
                    {"name": "absY", "value": abs(y), "unit": "m", "threshold": y_limit, "operator": "<="},
                ],
            ),
        )

    own_half_sign = defending_goal_sign(robot_side(robot), game["sides"])
    in_own_half = x <= POSITION_TOLERANCE if own_half_sign < 0 else x >= -POSITION_TOLERANCE
    center_distance = (x * x + y * y) ** 0.5
    center_threshold = field.circle_radius + POSITION_TOLERANCE
    in_center_circle = center_distance <= center_threshold
    if not in_own_half:
        if game["setPlay"] != "kickOff" or robot_side(robot) != game["kickingSide"] or not in_center_circle:
            sub_rule = "kickoff_kicking_side_outside_center" if game["setPlay"] == "kickOff" and robot_side(robot) == game["kickingSide"] else "outside_own_half"
            return CheckResult.pass_(
                reason="illegalPosition",
                evidence=illegal_position_evidence(
                    sub_rule,
                    "Robot is outside its own half and is not in an allowed kickoff center-circle position.",
                    position,
                    [
                        own_half_measurement(x, own_half_sign),
                        {"name": "centerDistance", "value": center_distance, "unit": "m", "threshold": center_threshold, "operator": "<="},
                    ],
                ),
            )

    if (game["setPlay"] != "kickOff" or robot_side(robot) != game["kickingSide"]) and in_center_circle:
        return CheckResult.pass_(
            reason="illegalPosition",
            evidence=illegal_position_evidence(
                "kickoff_non_kicking_side_in_center_circle",
                "Non-kicking-side robot is inside the kickoff center circle before the ball is free.",
                position,
                [
                    {"name": "centerDistance", "value": center_distance, "unit": "m", "threshold": center_threshold, "operator": ">"},
                ],
            ),
        )
    return CheckResult.fail()


def illegal_kickoff_position_before_ball_free(context: RuleContext, robot: dict[str, Any]) -> CheckResult:
    game = context.game
    if game.get("setPlay") != "kickOff" or game.get("kickingSide") is None or game.get("stopped"):
        return CheckResult.fail()
    tracker = context.trackers.get("set_play_runtime")
    active = getattr(tracker, "active", None)
    if active is not None and active.ball_free:
        return CheckResult.fail()
    return illegal_kickoff_position(context, robot, game)


