def set_play_complete(context: RuleContext, _subject: Any) -> CheckResult:
    game = context.game
    if game["state"] != "playing" or game["setPlay"] == "noSetPlay" or game["stopped"] or game["kickingSide"] is None:
        return CheckResult.fail()
    set_play_runtime = context.trackers.get("set_play_runtime")
    if set_play_runtime is None or not set_play_runtime.active:
        return CheckResult.fail()
    active = set_play_runtime.active
    if active.ball_free and active.kicking_side_moved_ball:
        return CheckResult.pass_(reason=active.ball_free_reason or "kicking_side_touch")
    if not active.kicking_side_moved_ball:
        return CheckResult.fail()
    contacts = list(context.facts.get("contacts") or [])
    kicking_side_touched = any(contact.side == game["kickingSide"] for contact in contacts)
    return CheckResult.pass_(reason="kicking_side_touch") if kicking_side_touched else CheckResult.fail()

def finish_set_play(context: RuleContext, _subject: Any, check: CheckResult) -> Iterable[RuleCommand]:
    reason = check.reason or "kicking_side_touch"
    yield RuntimeCommand("complete_active_set_play", {"lastTouchSide": context.game.get("kickingSide"), "reason": reason})
    yield ControlActionCommand({"type": "ballFree"})
    yield EmitEventCommand({
        "type": "ball_free",
        "source": "auto_referee",
        "outcome": {"reason": reason},
    })

    self.game["timeRemaining"] -= dt_seconds
    self.game["primaryTime"] = self.game["timeRemaining"]
    if self.game["timeRemaining"] <= 0 and self.game["phase"] != "penaltyShootout":
        if self.auto_advance_state:
            self._finish_if_time_limit_reached()

if run_always and self.game["secondaryTime"] > 0:
    self.game["secondaryTime"] = max(0, self.game["secondaryTime"] - dt_seconds)
    if self.game["secondaryTime"] <= 0 and self.auto_advance_state:
        self._handle_secondary_expired()
